# <=><=><=><=><=><=><=><=><=><=><=><=> disable security <=><=><=><=><=><=><=><=><=><=><=><=>
def disable_enb_security_admin(logger: logging.Logger) -> bool:
    """
    Disable security on enb - enable ssh access, disable ETH security, disable rnd port security via admin API.

    :param logger: An instance of logger
    :return: True or False whether finished with errors or not.
    """
    logger.debug("Disabling enb security via Admin API")
    admin = taf_admin()
    try:
        admin.connect_to()
        admin.disable_ethernet_port_security(timeout=30)
        admin.enable_ssh_access(timeout=30)
        admin.change_rnd_port_security(enable=True, timeout=30)
        logger.debug("ETH port security disabled, ssh access enabled, r&d port enabled successfully")
        return True
    except Exception as e:
        logger.error(
            f"Could not disable enb security due to an error: {e}",
            exc_info=True,
        )
        return False
    finally:
        try:
            admin.teardown()
        except Exception:
            pass


def disable_enb_security(logger: logging.Logger) -> None:
    """
    Disable security on enb - enable ssh access, disable ETH security, disable rnd port security.

    :param logger: An instance of logger
    """
    logger.debug("Starting deactivation of enb security for r&d purposes...")
    if not disable_enb_security_admin(logger):
        logger.error("There were problems with disabling security, some functionalities may not work correctly.")


# <=><=><=><=><=><=><=><=><=><=><=><=> detect tools <=><=><=><=><=><=><=><=><=><=><=><=>


def get_tl_location(tl_name: str) -> str:
    try:
        return UTE_CODE_TO_SITE_MAP[tl_name.split("_")[1]]
    except (IndexError, ValueError, KeyError):
        return "Unknown"


def get_testline(logger: logging.Logger) -> tuple[str, str]:
    tl_name = get_tl_name()
    tl_loc = get_tl_location(tl_name)
    logger.debug(f"Testline: {tl_name}, location: {tl_loc}")
    return tl_loc, tl_name


def get_tl_cfg(logger: logging.Logger) -> tuple[TestLine, bool]:
    """
    Get UTE TL configuration.
    :param logger: network logger
    :return: tuple of TAF_CONFIG from taf_config and bool as result
    """
    tl_cfg = get_taf_tl_config(logger)
    result = bool(tl_cfg)
    logger.debug(msg=f"Result: {result} TL config:\n{str(tl_cfg)}")
    return tl_cfg, result


def get_taf_tl_config(logger: logging.Logger) -> TestLine:
    """
    Fetch TestLine configuration based on TestLine name.

    :raise: ValueError
    :return: UTE (TAF) TestLine configuration as `TestLine`
    """
    tl_name = get_tl_name()
    module_path = get_config_module_path(logger, tl_name)
    config = load_tl_config(tl_name, module_path)
    return config.tl


def load_tl_config(tl_name, module_path):
    spec = spec_from_file_location(tl_name, module_path)
    config = module_from_spec(spec)  # type: ignore
    spec.loader.exec_module(config)  # type: ignore
    return config


def get_config_module_path(logger, tl_name):
    module_path = GERRIT_PATH / tl_name / "__init__.py"
    if not module_path.exists():
        raise Exception(f"Config doesn't exists! {module_path}")
    logger.info(f"Configuration path detected: {module_path}")
    return module_path.as_posix()


def get_tl_name() -> str:
    """
    Return testline name.

    :raise: AttributeError
    :return: testline name
    :rtype: str
    """
    vars_to_look_for_tl_name = {
        environ.get("SESSION_MANAGER", ""): re.compile("local/(.*?):"),
        uname()[1]: re.compile("(.*)"),
    }
    for var_value, var_re in vars_to_look_for_tl_name.items():
        if var_value and (match := var_re.search(var_value)):
            tl_name = match.group(1)
            tl_name = _parse_tl_name(tl_name)
            return tl_name
    else:
        return "UNKNOWN"


def _parse_tl_name(tl_name: str) -> str:
    """
    Parse testline name to fulfill naming conventions.

    :param tl_name: testline name
    :type tl_name: str
    :return: parsed testline name
    :rtype: str
    """
    not_single_testline = re.search(r"-\d+$", tl_name)  # name end with number
    if not_single_testline:
        tl_name = tl_name[: not_single_testline.start()]
    tl_name = tl_name.replace("-", "_")
    return tl_name.upper()


@lru_cache(maxsize=MAX_SUPPORTED_VMs)
def get_bts_rat(vm_id: int, tl_conf: TestLine, ttl_hash: int) -> str:
    del ttl_hash
    bts_tech_data: dict[str, str] = {}
    cache_file = pathlib.Path(CACHE_BTS_TECH)
    if cache_file.exists():
        with cache_file.open("r") as cache:
            bts_tech_data = json.load(cache)
            try:
                tech = bts_tech_data[f"{vm_id}"]
                assert tech != "UNKNOWN"
                return bts_tech_data[f"{vm_id}"]
            except (KeyError, AssertionError):
                pass
    bts_tech_data[f"{vm_id}"] = get_bts_tech(tl_conf, vm_id)
    with cache_file.open("w") as cache:
        json.dump(bts_tech_data, cache)
    return bts_tech_data[f"{vm_id}"]


def get_ttl_hash(seconds: int = 20) -> int:
    """Return the same value withing `seconds` time period"""
    return round(time.time() / seconds)


def is_4g(vm_id: int, tl_conf: TestLine) -> bool:
    """
    Base on testline name, check if TL is 4G.

    :param vm_id: id of VM
    :param tl_conf: TestLine configuration
    :return: True when testline is 5G ready
    """
    bts_rat = get_bts_rat(vm_id, tl_conf, get_ttl_hash())
    return bts_rat == "4G"


def is_5g(vm_id: int, tl_conf: TestLine) -> bool:
    """
    Base on testline name, check if TL is 5G.

    :param vm_id: id of VM
    :param tl_conf: TestLine configuration
    :return: True when testline is 5G ready
    """
    bts_rat = get_bts_rat(vm_id, tl_conf, get_ttl_hash())
    return bts_rat == "5G"


def get_bts_tech(tl_conf: TestLine, vm_id: int) -> str:
    """
    Check BTS technology based on TestLine configuration.
    """
    from taf.config.testline import CommonUnit, Connection
    from taf.transport.ssh import ssh

    try:
        tl_ssh_conn = tl_conf.test_pcs[vm_id - 1].default_ssh_connection_details
    except IndexError:
        raise ValueError(f"VM with id {vm_id} does not exist in TestLine configuration.")
    for connection in tl_conf.test_pcs[vm_id - 1].connections:
        # connections can be either Connection objects containing CommonUnit or components like CommonUnit
        if isinstance(connection, Connection):
            connection = connection.device
        if isinstance(connection, CommonUnit):
            lmp_conn = connection.lmp_connection
            ssh_manager = ssh()
            try:
                ssh_manager.connect_to(
                    tl_ssh_conn.addr, tl_ssh_conn.username, tl_ssh_conn.password, alias=f"proxy_vm_{vm_id}", timeout=5
                )
                ssh_manager.connect_to(
                    lmp_conn.addr,
                    lmp_conn.username,
                    lmp_conn.password,
                    proxy=f"proxy_vm_{vm_id}",
                    alias="bts",
                    timeout=5,
                )
                bts_tech = (
                    "4G"
                    if ssh_manager.execute("ps -ef | grep -i rrom | grep -v grep", connection="bts", timeout=5)
                    else "5G"
                )
                return bts_tech
            except Exception:
                return "UNKNOWN"
            finally:
                try:
                    ssh_manager.disconnect(f"proxy_vm_{vm_id}")
                    ssh_manager.disconnect("bts")
                except Exception:
                    pass
    raise ValueError("No BTS technology could be discovered based on TestLine configuration entries.")


# <=><=><=><=><=><=><=><=><=><=><=><=> file system tools <=><=><=><=><=><=><=><=><=><=><=><=>
def read_config(yaml_file: str) -> dict:
    """
    Read configuration from yaml file and return dict.

    :raise OSError: when yaml_file do not exist or is not a file
    :param yaml_file: absolute path to configuration yaml
    :return: configuration as dict
    """
    try:
        with open(yaml_file) as ymlfile:
            data = load(ymlfile, Loader=FullLoader)
    except (YAMLError, TypeError):
        data = {}
    return data


def write_config(data: dict, yaml_file: str, mode: str = "w") -> None:
    """
    Write python dict as yaml file.

    :raise OSError: when yaml_file do not exist or is not a file
    :param data: dict of configuration
    :param yaml_file: absolute path to configuration yaml
    :param mode: writing mode
    """
    with open(yaml_file, mode) as ymlfile:
        safe_dump(data, ymlfile, default_flow_style=False)


def save_result_data(data: tuple[dict, list, str], log_path: str, mode: str = "a") -> None:
    """
    Saves provided data to file using yaml method if it's (dict, list) or just puts in file otherwise
    :param data: data to save
    :param log_path: path to file where data should be stored
    :param mode: mode which should be used to open file
    """
    with Lock():
        if isinstance(data, (dict, list)):
            write_config(data, log_path, mode=mode)
        else:
            with open(log_path, mode) as summary_file:
                summary_file.write(f"{data}\n")


def create_dir(dir_path: str, raise_exc: bool = False) -> None:
    """Tries to create a directory and optionally raises exception"""
    try:
        makedirs(dir_path)
        # todo: when only PY3 supported remove and use: makedirs(name=log_dir, exist_ok=True)
    except OSError:
        if raise_exc:
            raise


def _create_symlink(symlink_target, symlink_name):
    try:
        remove(symlink_name)
    except OSError:
        pass
    finally:
        symlink(symlink_target, symlink_name)


def create_dir_for_logs(logger: logging.Logger, log_dir_path: str) -> tuple[str, str]:
    """
    Prepares a directory to store logs
    :param logger: network logger
    :param log_dir_path: path to root logs dir
    :return: path to newly created directory
    """
    log_dir_path = str(log_dir_path)
    current_datetime = get_current_datetime()
    temporary_log_dir = path.join("/tmp", "logcollector", current_datetime)
    new_log_dir = path.join(log_dir_path, current_datetime)
    for dir_path in [temporary_log_dir, new_log_dir]:
        create_dir(dir_path)
        logger.debug(f"created directory = {dir_path}")
    _create_symlink(new_log_dir, path.join(log_dir_path, "latest"))
    return new_log_dir, temporary_log_dir


# <=><=><=><=><=><=><=><=><=><=><=><=> network tools <=><=><=><=><=><=><=><=><=><=><=><=>
def upload_files(
    logger: logging.Logger, hosts: dict[str, vm_host], local_paths: list[str], remote_paths: list[str] | None = None
) -> None:
    """
    Upload files from file_path to all hosts to the same remote_paths location.
    When remote_paths is skipped all files from local_paths will be copied to the same remote location.

    :param logger: network logger
    :param hosts: namedtuple with addr, usr, passwd of remote host
    :param local_paths: list with full path to local file
    :param remote_paths: list with full path to remote file
    """
    if not remote_paths:
        remote_paths = local_paths
    futures = []
    with ThreadPoolExecutor(max_workers=len(hosts) + len(local_paths)) as th_executor:
        for host_data in hosts.values():
            logger.debug(f"Upload {local_paths} to {host_data.addr}")
            futures.append(
                th_executor.submit(
                    copy_to_remote_location,
                    logger,
                    host_data.addr,
                    host_data.usr,
                    host_data.passwd,
                    local_paths,
                    remote_paths,
                )
            )
        wait(futures, timeout=20)


def remove_files(logger: logging.Logger, hosts: dict[str, vm_host], remote_paths: list[str]) -> None:
    """
    Remove files from remote_paths in all hosts.

    :param logger: network logger
    :param hosts: namedtuple with addr, usr, passwd of remote host
    :param remote_paths: list with full path to remote file
    """
    futures = []
    with ThreadPoolExecutor(max_workers=len(hosts)) as th_executor:
        for host_data in hosts.values():
            logger.debug(f"Remove {host_data.addr}")
            futures.append(
                th_executor.submit(
                    remove_in_remote_location,
                    logger,
                    host_data.addr,
                    host_data.usr,
                    host_data.passwd,
                    remote_paths,
                )
            )
        wait(futures, timeout=20)


# <=><=><=><=><=><=><=><=><=><=><=><=> others tools <=><=><=><=><=><=><=><=><=><=><=><=>
def get_current_datetime() -> str:
    """Gets current datetime in format YYYYMMDD_hhmmss"""
    return datetime.strftime(datetime.now(), "%y%m%d_%H%M%S")


def new_version_exists(lib_name: str, ver_installed: str) -> tuple[bool, str]:
    """
    Check if new version of library exists.

    :param lib_name: name of library to check
    :param ver_installed: current version of library
    :return: tuple of (True, version) if new version exists, (False, '') otherwise
    """
    try:
        with closing(request.urlopen(f"{NOKIA_PYPI}/{lib_name}/")) as pypi_web:
            html = pypi_web.read().decode()
            lib_versions = findall(rf"{lib_name}-((?:\d*\.){{2}}\d*)", html)
    except error.URLError:
        return False, ""
    lib_versions = list(set(lib_versions))
    lib_versions.sort(key=lambda s: list(map(int, s.split("."))))
    latest = lib_versions[-1]
    return version.parse(ver_installed) < version.parse(latest), latest


def rpartial(func, *args, **kwargs):
    """
    Right side copy of functools.partial.
    Example:
        f = rpartial(foo, 1, 2, a=3, b=4)
        f(5, 6)  # is equivalent to foo(5, 6, 1, 2, a=3, b=4)
    :param func: function be called
    :param args: arguments to be added to the function as last args call (at right side)
    :param kwargs: keyword arguments to be added to the function call
    :return: partial object which when called will behave like func called with args and kwargs,
    but args will be appended to the right side
    """

    @wraps(func)
    def _newfunc(*fargs, **fkeywords):
        newkeywords = deepcopy(kwargs)
        newkeywords.update(fkeywords)
        return func(*(fargs + args), **newkeywords)

    _newfunc.func = func
    _newfunc.args = args
    _newfunc.kwargs = kwargs
    _newfunc.name = func.__name__
    return _newfunc


def get_hw_type(logger: logging.Logger, data: dict) -> str:
    """
    Get hardware type of eNB.
    :return: type of platform
    """
    _platform, _ = run_remote_cmd(logger=logger, cmd="cat /proc/device-tree/module-identity/unit-id", **data)
    _platform = _platform.strip("\x00")
    if _platform in FSMR3_IDS:
        hw_type = "FSMR3"
    else:
        hw_type = "AIRSCALE"
    logger.debug(f"Detected hardware type: {hw_type}")
    return hw_type


def merge_dicts(*dicts: list[dict]) -> dict[Any, Any]:
    """Merges provided dictionaries into one"""
    result = {}
    for dictionary in dicts:
        result.update(dictionary)
    return result
